/**
 * Build script for weather condition icons.
 *
 * Reads every collection in src/weather-condition-icons/<slug>/manifest.json
 * (`slug`, `label`, `description`, `icons`, `conditionMappings`), optimises
 * each SVG via SVGO, writes the results to build/weather-condition-icons/<slug>/,
 * and generates build/weather-condition-icons-manifest.php, which
 * RegisterConditionIcons reads to register the collections.
 *
 * The plugin's own collections (cirrus, cumulus, nimbus, in outline and solid)
 * are generated by scripts/generate-weather-condition-icons/; "elio" is the
 * original Tabler-based one.
 *
 * Inspired by Gutenberg's packages/icons/lib/generate-manifest-php.cjs.
 */

import {
	readFileSync,
	writeFileSync,
	mkdirSync,
	readdirSync,
	existsSync,
} from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';
import { optimize } from 'svgo';

const __dirname = dirname( fileURLToPath( import.meta.url ) );
const ROOT = resolve( __dirname, '..' );

const SRC_DIR = resolve( ROOT, 'src/weather-condition-icons' );
const BUILD_DIR = resolve( ROOT, 'build/weather-condition-icons' );
const MANIFEST_PHP = resolve(
	ROOT,
	'build/weather-condition-icons-manifest.php'
);

/**
 * SVGO base configuration — strip editor metadata. The viewBox stays: SVGO 4
 * no longer removes it in preset-default.
 */
const SVGO_CONFIG_BASE = {
	plugins: [ 'preset-default', 'removeDimensions' ],
};

/**
 * Extra SVGO plugin for stroke icons: replace hardcoded stroke colors with
 * currentColor so the icon inherits its color from CSS.
 */
const SVGO_PLUGIN_STROKE_TO_CURRENT_COLOR = {
	name: 'strokeToCurrentColor',
	fn: () => ( {
		element: {
			enter( node ) {
				if (
					node.attributes.stroke &&
					node.attributes.stroke !== 'none' &&
					node.attributes.stroke !== 'currentColor'
				) {
					node.attributes.stroke = 'currentColor';
				}
			},
		},
	} ),
};

/**
 * Builds the SVGO config for a given icon style.
 *
 * Stroke icons lose their stroke-width: the condition icon block sets it.
 *
 * @param {'stroke'|'fill'|string} style Icon style.
 * @return {import('svgo').Config} SVGO config.
 */
function svgoConfig( style ) {
	if ( style === 'stroke' ) {
		return {
			...SVGO_CONFIG_BASE,
			plugins: [
				...SVGO_CONFIG_BASE.plugins,
				SVGO_PLUGIN_STROKE_TO_CURRENT_COLOR,
				{
					name: 'removeAttrs',
					params: {
						attrs: [ 'stroke-width' ],
					},
				},
			],
		};
	}
	return SVGO_CONFIG_BASE;
}

/**
 * Escapes a string for use inside a PHP single-quoted string.
 *
 * @param {string} str String to escape.
 * @return {string} Escaped string.
 */
function escapeSingleQuote( str ) {
	return str.replace( /\\/g, '\\\\' ).replace( /'/g, "\\'" );
}

/**
 * The collection the plugin falls back to: registered first, so the pickers list it first.
 */
const DEFAULT_COLLECTION = 'elio';

/**
 * Reads the manifest of every collection folder: the default collection first,
 * then the others in folder order.
 *
 * @return {Array<Object>} Manifests, each with its `dir`.
 */
function readManifests() {
	return readdirSync( SRC_DIR, { withFileTypes: true } )
		.filter( ( entry ) => entry.isDirectory() )
		.map( ( entry ) => entry.name )
		.filter( ( name ) =>
			existsSync( resolve( SRC_DIR, name, 'manifest.json' ) )
		)
		.sort( ( a, b ) => {
			if ( a === DEFAULT_COLLECTION || b === DEFAULT_COLLECTION ) {
				return a === DEFAULT_COLLECTION ? -1 : 1;
			}
			return a.localeCompare( b );
		} )
		.map( ( name ) => resolve( SRC_DIR, name ) )
		.map( ( dir ) => ( {
			dir,
			...JSON.parse(
				readFileSync( resolve( dir, 'manifest.json' ), 'utf8' )
			),
		} ) );
}

const manifests = readManifests();

if ( manifests.length === 0 ) {
	process.stderr.write(
		`Error: no <collection>/manifest.json found in ${ SRC_DIR }.\n`
	);
	process.exit( 1 );
}

const phpLines = [
	'<?php',
	'// This file is automatically generated. Do not edit directly.',
	"if ( ! defined( 'ABSPATH' ) ) {",
	"    die( 'Silence is golden.' );",
	'}',
	'',
	'return array(',
	"    'collections' => array(",
];

let builtCount = 0;
let mappingCount = 0;

for ( const manifest of manifests ) {
	const { slug, label, description, icons, conditionMappings, dir } =
		manifest;

	if (
		typeof slug !== 'string' ||
		typeof label !== 'string' ||
		! Array.isArray( icons ) ||
		! Array.isArray( conditionMappings )
	) {
		process.stderr.write(
			`Error: ${ dir }/manifest.json must have "slug", "label", "icons" and "conditionMappings".\n`
		);
		process.exit( 1 );
	}

	const buildDir = resolve( BUILD_DIR, slug );
	mkdirSync( buildDir, { recursive: true } );

	const maxSlugLen = Math.max( ...icons.map( ( e ) => e.slug.length ) );
	const keyWidth = maxSlugLen + 2 + 3;

	phpLines.push( `        '${ escapeSingleQuote( slug ) }' => array(` );
	phpLines.push(
		`            'label'             => _x( '${ escapeSingleQuote( label ) }', 'icon collection label', 'elio-blocks' ),`
	);
	phpLines.push(
		`            'description'       => __( '${ escapeSingleQuote( description ?? '' ) }', 'elio-blocks' ),`
	);
	phpLines.push( "            'icons'             => array(" );

	for ( const entry of icons ) {
		const { slug: iconSlug, label: iconLabel, filePath } = entry;

		const srcPath = resolve( dir, filePath );
		let svgSource;
		try {
			svgSource = readFileSync( srcPath, 'utf8' );
		} catch {
			process.stderr.write(
				`Warning: could not read ${ srcPath }, skipping.\n`
			);
			continue;
		}

		const { data: svgOptimised } = optimize(
			svgSource,
			svgoConfig( entry.style )
		);

		writeFileSync( resolve( buildDir, filePath ), svgOptimised, 'utf8' );
		builtCount++;

		const phpKey = `'${ iconSlug }'`.padEnd( keyWidth );

		phpLines.push( `                ${ phpKey }=> array(` );
		phpLines.push(
			`                    'label'    => _x( '${ escapeSingleQuote( iconLabel ) }', 'icon label', 'elio-blocks' ),`
		);
		phpLines.push(
			`                    'filePath' => '${ escapeSingleQuote( filePath ) }',`
		);
		phpLines.push(
			`                    'style'    => '${ entry.style ?? 'fill' }',`
		);
		phpLines.push( '                ),' );
	}

	phpLines.push( '            ),' );
	phpLines.push( "            'conditionMappings' => array(" );

	for ( const mapping of conditionMappings ) {
		const { condition, dayOrNight, iconSlug } = mapping;
		phpLines.push( '                array(' );
		phpLines.push(
			`                    'condition'  => '${ condition }',`
		);
		phpLines.push(
			`                    'dayOrNight' => '${ dayOrNight }',`
		);
		phpLines.push( `                    'iconSlug'   => '${ iconSlug }',` );
		phpLines.push( '                ),' );
		mappingCount++;
	}

	phpLines.push( '            ),' );
	phpLines.push( '        ),' );
}

phpLines.push( '    ),' );
phpLines.push( ');', '' );

writeFileSync( MANIFEST_PHP, phpLines.join( '\n' ), 'utf8' );

process.stdout.write(
	`Built ${ manifests.length } collections: ${ builtCount } icons + ${ mappingCount } mappings → ${ BUILD_DIR }\n` +
		`Generated manifest → ${ MANIFEST_PHP }\n`
);
